        return out
    height, width = len(grid), len(grid[0])
    for c in range(width):
        if grid[-1][c] != 5:
            continue
        # Each original nonzero pixel along the beam column acts as a source;
        # in the observed examples, the beam fills the empty span around sources.
        for r in range(height):
            if out[r][c] == 0:
                # provisional rule: extend the closest nonzero pixel in this column
                sources = [rr for rr in range(height) if grid[rr][c] != 0]
                if sources:
                    nearest = min(sources, key=lambda rr: abs(rr-r))
                    out[r][c] = grid[nearest][c]
